def is_prime(n):
    # عددهای کمتر از ۲ اول نیستند
    if n < 2:
        return False

    # اگر n بر یکی از عددهای ۲ تا n-1 بخش‌پذیر باشد، اول نیست
    for d in range(2, n):
        if n % d == 0:
            return False

    # هیچ مقسوم‌علیهی پیدا نشد، پس اول است
    return True

# تابعی که یک عملیات ساده را انجام می‌دهد و نتیجه را در متغیر نگه می‌دارد
def compute(a, op, b):
    # نتیجه را از صفر شروع می‌کنیم
    result = 0.0

    # انتخاب عملیات بر اساس عملگر
    if op == "+":
        result = a + b
    elif op == "-":
        result = a - b
    elif op == "*":
        result = a * b
    else:
        result = a / b

    # برگرداندن نتیجه
    return result

